UPDATE emp57_addr_book_group
   SET emp57_group_nm  = #{r.groupName},
       emp57_public_yn = #{r.publicYn}
 WHERE emp57_addr_book_group_id = #{id}
   AND emp57_company_id         = #{companyId}
   AND emp57_parent_id          = 0

UPDATE emp57_addr_book_group
   SET emp57_note = #{r.note}
 WHERE emp57_addr_book_group_id = #{r.addrBookGroupId}
   AND emp57_company_id         = #{companyId}
   AND emp57_parent_id          <> 0

